import { FileSystem } from "@effect/platform"
import { Effect, Schema } from "effect"
import { EvidenceCollection, type Evidence } from "../domain/Evidence.js"
import { ExpectedOutcome, type ExpectedOutcome as ExpectedOutcomeType } from "../domain/ExpectedOutcome.js"
import { Incident, type Incident as IncidentType } from "../domain/Incident.js"
import { decodePersisted } from "../domain/Common.js"
import type { IncidentContext } from "../domain/IncidentContext.js"
import { DatasetMalformed, DatasetNotFound, SchemaValidationFailed } from "../errors/DatasetErrors.js"
import { decodeContext } from "../context/ContextValidator.js"

export interface IncidentDataset {
  readonly directory: string
  readonly incident: IncidentType
  readonly evidence: ReadonlyArray<Evidence>
  readonly context: IncidentContext
  readonly expected: ExpectedOutcomeType
  readonly rawContext: unknown
}

const readJson = (path: string) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem
    const exists = yield* fs.exists(path).pipe(Effect.mapError(() => new DatasetNotFound({ path })))
    if (!exists) return yield* Effect.fail(new DatasetNotFound({ path }))
    const contents = yield* fs.readFileString(path).pipe(
      Effect.mapError((error) => new DatasetMalformed({ path, reason: String(error) }))
    )
    return yield* Effect.try({
      try: () => JSON.parse(contents) as unknown,
      catch: (error) => new DatasetMalformed({ path, reason: String(error) })
    })
  })

const decode = <A, I>(schema: Schema.Schema<A, I>, raw: unknown, path: string) =>
  decodePersisted(schema)(raw).pipe(
    Effect.mapError(() => new SchemaValidationFailed({ path, reason: "Input does not match its strict persisted artifact contract" }))
  )

export const loadIncidentDataset = (directory: string) =>
  Effect.gen(function* () {
    const incidentPath = `${directory}/incident.json`
    const evidencePath = `${directory}/evidence.json`
    const contextPath = `${directory}/context.json`
    const expectedPath = `${directory}/expected.json`
    const [incidentRaw, evidenceRaw, contextRaw, expectedRaw] = yield* Effect.all(
      [readJson(incidentPath), readJson(evidencePath), readJson(contextPath), readJson(expectedPath)],
      { concurrency: 4 }
    )
    const [incident, evidence, context, expected] = yield* Effect.all([
      decode(Incident, incidentRaw, incidentPath),
      decode(EvidenceCollection, evidenceRaw, evidencePath),
      decodeContext(contextRaw, contextPath),
      decode(ExpectedOutcome, expectedRaw, expectedPath)
    ])
    return { directory, incident, evidence, context, expected, rawContext: contextRaw } satisfies IncidentDataset
  })

import { Effect } from "effect"
import type { Evidence } from "../domain/Evidence.js"
import { IncidentContext, type IncidentContext as IncidentContextType } from "../domain/IncidentContext.js"
import { decodePersisted } from "../domain/Common.js"
import { ContextContainsHypothesis, ContextEvidenceReferenceMissing } from "../errors/ContextErrors.js"
import { SchemaValidationFailed } from "../errors/DatasetErrors.js"
import { contextByteSize, validateContextBudget } from "./ContextBudget.js"

const forbiddenInferenceKeys = new Set(["hypothesis", "hypotheses", "rootcause", "rootcauses"])

const findForbiddenInferencePath = (value: unknown, path = "$", seen = new Set<unknown>()): string | undefined => {
  if (value === null || typeof value !== "object" || seen.has(value)) return undefined
  seen.add(value)
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const found = findForbiddenInferencePath(value[index], `${path}[${index}]`, seen)
      if (found !== undefined) return found
    }
    return undefined
  }
  for (const [key, child] of Object.entries(value)) {
    const normalized = key.replace(/[^a-z]/gi, "").toLowerCase()
    if (forbiddenInferenceKeys.has(normalized)) return `${path}.${key}`
    const found = findForbiddenInferencePath(child, `${path}.${key}`, seen)
    if (found !== undefined) return found
  }
  return undefined
}

export const decodeContext = (raw: unknown, path = "context.json") => {
  return Effect.gen(function* () {
    const forbiddenPath = findForbiddenInferencePath(raw)
    if (forbiddenPath !== undefined) yield* Effect.fail(new ContextContainsHypothesis({ path: forbiddenPath }))
    return yield* decodePersisted(IncidentContext)(raw).pipe(
      Effect.mapError(() => new SchemaValidationFailed({ path, reason: "Input does not match the strict IncidentContext contract" }))
    )
  })
}

export const referencedEvidenceIds = (context: IncidentContextType): ReadonlySet<string> => {
  const ids = new Set(context.evidenceReferences)
  for (const item of [...context.facts, ...context.recentChanges, ...context.errors, ...context.timeline, ...context.dependencies]) {
    for (const id of item.evidenceIds) ids.add(id)
  }
  return ids

